function is_undulating(n){
    if (n.toString().length < 3) return false; // A number with less than 3 digits cannot be undulating

    let isIncreasing = true;
    let isDecreasing = true;

    for (let i = 0; i < n.toString().length - 1; i++) {
        if (n.toString()[i] > n.toString()[i + 1]) {
            isIncreasing = false;
        }
        if (n.toString()[i] < n.toString()[i + 1]) {
            isDecreasing = false;
        }
    }

    return isIncreasing || isDecreasing;
}

